package fleetflow;
import java.util.*;
public class Module5 {
 public static void menu(Scanner sc){while(true){System.out.println("\n--- MODULE 5: NP-COMPLETENESS & APPROXIMATION ---\n1. Subset sum (decision)\n2. Vertex-cover 2-approximation\n3. Greedy LPT load balancing\n4. 0/1 knapsack demo\n0. Back");int c=Util.readInt(sc,"Choice: ");if(c==0)return;switch(c){case 1:int n=Util.readInt(sc,"Number of values: ");int[]a=new int[n];for(int i=0;i<n;i++)a[i]=Util.readInt(sc,"Value "+i+": ");int target=Util.readInt(sc,"Target sum: ");System.out.println("Subset exists: "+subsetSum(a,target));break;case 2:int v=Util.readInt(sc,"Vertices (0-based count): "),e=Util.readInt(sc,"Edges: ");List<int[]>edges=new ArrayList<>();for(int i=0;i<e;i++)edges.add(new int[]{Util.readInt(sc,"u: "),Util.readInt(sc,"v: ")});System.out.println("Approximate cover vertices: "+vertexCover(v,edges));break;case 3:int jobs=Util.readInt(sc,"Number of job durations: ");int[]times=new int[jobs];for(int i=0;i<jobs;i++)times[i]=Util.readInt(sc,"Job "+i+": ");int machines=Util.readInt(sc,"Machines: ");System.out.println("Machine loads (LPT): "+lpt(times,machines));break;case 4:int k=Util.readInt(sc,"Items: ");int[]w=new int[k],val=new int[k];for(int i=0;i<k;i++){w[i]=Util.readInt(sc,"Weight: ");val[i]=Util.readInt(sc,"Value: ");}int cap=Util.readInt(sc,"Capacity: ");System.out.println("Optimal value = "+Module3.knapsack(w,val,cap));break;default:System.out.println("Invalid choice.");}}}
 public static boolean subsetSum(int[]a,int t){if(t<0)return false;boolean[]d=new boolean[t+1];d[0]=true;for(int x:a)if(x>=0)for(int j=t;j>=x;j--)d[j]|=d[j-x];return d[t];}
 public static List<Integer> vertexCover(int n,List<int[]>edges){boolean[]covered=new boolean[n],chosen=new boolean[n];for(int[]e:edges){int u=e[0],v=e[1];if(u<0||u>=n||v<0||v>=n)continue;if(!covered[u]&&!covered[v]){chosen[u]=chosen[v]=true;covered[u]=covered[v]=true;}}List<Integer>r=new ArrayList<>();for(int i=0;i<n;i++)if(chosen[i])r.add(i);return r;}
 public static int[] lpt(int[]jobs,int m){if(m<=0)return new int[0];Integer[]a=Arrays.stream(jobs).boxed().toArray(Integer[]::new);Arrays.sort(a,Collections.reverseOrder());int[]load=new int[m];for(int x:a){int k=0;for(int i=1;i<m;i++)if(load[i]<load[k])k=i;load[k]+=x;}return load;}
}
